import "server-only";
import { cookies } from "next/headers";
import { db } from "./db";
import { getCurrentUser } from "./auth";

const CART_COOKIE = "sm_cart";
export const MAX_QTY = 20;

async function setCartCookie(id: string) {
  (await cookies()).set(CART_COOKIE, id, {
    httpOnly: true,
    secure: process.env.NODE_ENV === "production",
    sameSite: "lax",
    path: "/",
    maxAge: 60 * 60 * 24 * 60,
  });
}

/** Find the visitor's cart (by user, else by cookie). Guest carts are merged into the user's on login. */
export async function findCart() {
  const user = await getCurrentUser();
  const cookieId = (await cookies()).get(CART_COOKIE)?.value;
  if (user) {
    const cart = await db.cart.findFirst({ where: { userId: user.id }, orderBy: { updatedAt: "desc" } });
    if (cart) return cart;
  }
  if (cookieId) {
    const cart = await db.cart.findUnique({ where: { id: cookieId } });
    if (cart && (!cart.userId || cart.userId === user?.id)) return cart;
  }
  return null;
}

export async function getOrCreateCart() {
  const existing = await findCart();
  if (existing) return existing;
  const user = await getCurrentUser();
  const cart = await db.cart.create({ data: { userId: user?.id ?? null } });
  await setCartCookie(cart.id);
  return cart;
}

export async function getCartItems() {
  const cart = await findCart();
  if (!cart) return [];
  return db.cartItem.findMany({
    where: { cartId: cart.id },
    include: {
      product: {
        select: {
          id: true, name: true, slug: true, price: true, mrp: true, stock: true, isActive: true,
          engravingAvailable: true, images: { orderBy: { sortOrder: "asc" }, take: 1 },
        },
      },
    },
    orderBy: { id: "asc" },
  });
}

export async function cartCount() {
  const cart = await findCart();
  if (!cart) return 0;
  const agg = await db.cartItem.aggregate({ where: { cartId: cart.id }, _sum: { quantity: true } });
  return agg._sum.quantity ?? 0;
}

/** Called right after login/registration: attach the guest cart to the user. */
export async function mergeGuestCart(userId: string) {
  const cookieId = (await cookies()).get(CART_COOKIE)?.value;
  if (!cookieId) return;
  const guest = await db.cart.findUnique({ where: { id: cookieId }, include: { items: true } });
  if (!guest || (guest.userId && guest.userId !== userId)) return;
  const userCart = await db.cart.findFirst({ where: { userId, id: { not: guest.id } }, orderBy: { updatedAt: "desc" } });
  if (!userCart) {
    await db.cart.update({ where: { id: guest.id }, data: { userId } });
    return;
  }
  for (const item of guest.items) {
    await db.cartItem.upsert({
      where: { cartId_productId_engravingText: { cartId: userCart.id, productId: item.productId, engravingText: item.engravingText } },
      create: { cartId: userCart.id, productId: item.productId, quantity: item.quantity, engravingText: item.engravingText },
      update: { quantity: { increment: item.quantity } },
    });
  }
  await db.cart.delete({ where: { id: guest.id } });
  await setCartCookie(userCart.id);
}
